pub enum Msg {
    Ping,
    Hello(String),
}

const CURRENT_VERSION: &str = "v1";

pub fn decode(bytes: &str) -> Result<Msg, String> {
    let input = bytes.trim();
    match input {
        "ping" | "v1:ping" => Ok(Msg::Ping),
        _ if input.starts_with("v:2:hello:") => Ok(Msg::Hello(input[10..].to_owned())),
        _ => Err("unknown".into()),
    }
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!("v:2:hello:{}", value),
    }
}

pub fn encode_versioned(msg: &Msg) -> String {
    match msg {
        Msg::Ping => format!("{}:{}", CURRENT_VERSION, encode(msg)),
        Msg::Hello(value) => format!("v:2:hello:{}", value),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn ping_encode_roundtrip() {
        assert!(matches!(decode(&encode(&Msg::Ping)), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_v2_encode_roundtrip() {
        let message = Msg::Hello("client-42".into());
        assert!(matches!(decode(&encode(&message)), Ok(Msg::Hello(value)) if value == "client-42"));
    }
}
